files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #F0F0F0;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #1a5cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #1a5cff;
  --vt-accent-on-deep: #1a5cff;
  --vt-line: #eaeaea;

  background: var(--vt-surface);
  font-family: 'Open Sans', sans-serif;
  color: var(--vt-ink);
}

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: var(--vt-surface);
  box-shadow: 0 2px 5px rgba(0,0,0,0.1);
  z-index: 1000;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1140px;
  margin: 0 auto;
  padding: 10px 15px;
  height: 74px;
}

.logo {
  font-size: 24px;
  font-weight: 700;
  color: var(--vt-accent);
  text-decoration: none;
  display: flex;
  align-items: center;
}

.brand {
  display: flex;
  flex-direction: column;
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  font-weight: 600;
  font-size: 16px;
  transition: color 0.3s;
}

.navLinks a:hover,
.navLinks a:focus-visible {
  color: var(--vt-ink);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.hero {
  position: relative;
  overflow: hidden;
  height: 580px;
  margin-top: 74px;
}

.heroSlider {
  position: absolute;
  inset: 0;
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}

.slide {
  flex: 0 0 100%;
  scroll-snap-align: start;
}

.slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.heroText {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 50%;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  z-index: 2;
  box-shadow: 0 0 10px rgba(0,0,0,0.1);
}

.heroText h1 {
  margin: 0 0 0.5rem;
  font-size: 48px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--vt-ink);
}

.heroText p {
  margin: 0 0 1rem;
  font-size: 18px;
  line-height: 1.6;
  color: var(--vt-ink-soft);
}

.heroLinks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
}

.customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: top 0.3s ease;
}

.customLink:hover::before,
.customLink:focus-visible::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
}

.phoneIcon {
  display: inline-block;
  width: 16px;
  height: 16px;
  background: var(--vt-accent);
  border-radius: 50%;
  margin-right: 6px;
  vertical-align: middle;
}

.section {
  padding: 7rem 15px;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.aboutRow {
  display: flex;
  justify-content: center;
}

.aboutContent {
  max-width: 800px;
}

.aboutContent h2 {
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 1.5rem;
  color: var(--vt-ink);
}

.aboutContent p {
  font-size: 18px;
  line-height: 1.6;
  color: var(--vt-ink-soft);
  margin-bottom: 1rem;
}

.gallerySection {
  padding: 0 0 7rem;
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
  margin: 0 -15px;
}

.galleryItem {
  width: 50%;
  padding: 0;
}

.galleryItem img {
  width: 100%;
  height: auto;
  display: block;
}

.timelineSection {
  padding: 7rem 0 0;
}

.sectionTitle {
  text-align: center;
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 3rem;
  color: var(--vt-ink);
}

.timeline {
  position: relative;
  max-width: 900px;
  margin: 0 auto;
}

.timeline::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
  background: var(--vt-line);
  transform: translateX(-50%);
  z-index: 0;
}

.timelineNode {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  position: relative;
  margin-bottom: 3rem;
}

.timelineNode.odd {
  /* content left */
}

.timelineNode.even {
  flex-direction: row-reverse;
}

.timelineContent {
  flex: 0 0 45%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  border-radius: 0 0 0.25rem 0.25rem;
  overflow: visible;
  position: relative;
  z-index: 1;
}

.timelineContent h3 {
  background: var(--vt-ink);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
  margin: 0;
  font-size: 24px;
}

.timelineNode.odd .timelineContent h3::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  border-left: 10px solid var(--vt-ink);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode.even .timelineContent h3::after {
  content: '';
  position: absolute;
  top: 50%;
  right: 100%;
  left: auto;
  transform: translateY(-50%);
  border-right: 10px solid var(--vt-ink);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineContent p {
  padding: 10px 30px;
  color: var(--vt-ink-soft);
  margin: 0;
  font-size: 16px;
  line-height: 1.6;
}

.timelineIcon {
  flex: 0 0 auto;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0,0,0,0.175);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
}

.timelineIcon span {
  color: var(--vt-accent);
  font-size: 32px;
  font-weight: 700;
}

.timelineDate {
  flex: 0 0 40%;
  padding-top: 20px;
  font-size: 16px;
  color: var(--vt-ink-soft);
}

.timelineNode.odd .timelineDate {
  text-align: left;
}

.timelineNode.even .timelineDate {
  text-align: right;
}

.price {
  display: block;
  margin-top: 0.5rem;
  font-weight: 600;
  color: var(--vt-ink);
}

.footer {
  background: var(--vt-surface-2);
  padding: 5rem 0 2rem;
  margin-top: 7rem;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.footerColHours,
.footerColContact,
.footerColSocial,
.footerColCopyright {
  flex: 1 1 200px;
}

.footer h5 {
  font-size: 20px;
  font-weight: 600;
  margin-bottom: 1rem;
  color: var(--vt-ink);
}

.footer p {
  font-size: 16px;
  color: var(--vt-ink-soft);
  margin: 0.5rem 0;
}

.footer a {
  color: var(--vt-accent);
  text-decoration: none;
}

.footer a:hover {
  text-decoration: underline;
}

.socialLinks {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  gap: 1rem;
}

.socialLinks a {
  font-size: 24px;
  color: var(--vt-accent);
  transition: color 0.3s;
}

.socialLinks a:hover {
  color: var(--vt-ink);
}

.copyright {
  font-size: 14px;
  color: var(--vt-ink-soft);
  margin-top: 2rem;
}

/* Responsive */
@media (max-width: 991px) {
  .hero {
    height: auto;
    margin-top: 74px;
  }

  .heroSlider {
    position: relative;
    height: auto;
  }

  .slide img {
    height: auto;
  }

  .heroText {
    position: relative;
    bottom: auto;
    right: auto;
    width: auto;
    padding: 2rem;
    margin-top: -100px;
    margin-bottom: -100px;
  }

  .section {
    padding: 5rem 15px;
  }

  .gallerySection {
    padding: 0 0 5rem;
  }

  .timelineSection {
    padding: 5rem 0 0;
  }
}

@media (max-width: 767px) {
  .navIn {
    flex-direction: column;
    height: auto;
    padding: 10px 0;
  }

  .navLinks {
    flex-wrap: wrap;
    justify-content: center;
    gap: 0.5rem 1rem;
    margin-top: 10px;
  }

  .heroText {
    padding: 1.5rem;
  }

  .heroText h1 {
    font-size: 38px;
  }

  .timeline::before {
    left: 40px;
  }

  .timelineNode,
  .timelineNode.even {
    flex-direction: column;
    align-items: flex-start;
    margin-left: 80px;
  }

  .timelineContent {
    order: 2;
    flex: 1 1 auto;
    width: 100%;
  }

  .timelineIcon {
    order: 1;
    margin-bottom: 1rem;
    align-self: flex-start;
  }

  .timelineDate {
    order: 3;
    flex: 1 1 auto;
    text-align: left !important;
    padding-top: 0.5rem;
  }

  .timelineNode.odd .timelineContent h3::after {
    left: auto;
    right: 100%;
    border-left: 0;
    border-right: 10px solid var(--vt-ink);
  }

  .timelineNode.even .timelineContent h3::after {
    right: 100%;
    left: auto;
    border-right: 10px solid var(--vt-ink);
    border-left: 0;
  }
}

@media (max-width: 575px) {
  .heroText h1 {
    font-size: 32px;
  }

  .heroLinks {
    flex-direction: column;
    align-items: flex-start;
  }

  .galleryItem {
    width: 100%;
  }

  .timeline::before {
    left: 25px;
  }

  .timelineNode,
  .timelineNode.even {
    margin-left: 50px;
  }

  .timelineIcon {
    width: 60px;
    height: 60px;
  }

  .timelineIcon span {
    font-size: 24px;
  }
}

@media (max-width: 360px) {
  .heroText h1 {
    font-size: 28px;
  }

  .customLink {
    padding: 0 20px;
    line-height: 30px;
    font-size: 12px;
  }
}
